monitor MutexMonitor
    var locked: boolean;
    var access: condition;

    entry procedure Lock
    begin
        if locked then access.wait;
        locked := true;
    end Lock;

    entry procedure Unlock
    begin
        locked := false;
        access.signal;
    end Unlock;
begin
    locked := false;
end MutexMonitor;

// --- Producer-Consumer in Hoare Monitor ---
monitor Buffer
    var place: array [0..N-1] of ARTICLE;
    var head, tail, nbElements: integer;
    var notFull, notEmpty: condition;

    entry procedure put(a: ARTICLE)
    begin
        if nbElements = N then notFull.wait;
        nbElements := nbElements + 1;
        place[head] := a;
        head := (head + 1) mod N;
        notEmpty.signal;
    end put;

    entry procedure get(var a: ARTICLE)
    begin
        if nbElements = 0 then notEmpty.wait;
        a := place[tail];
        nbElements := nbElements - 1;
        tail := (tail + 1) mod N;
        notFull.signal;
    end get;
begin
    nbElements := 0; tail := 0; head := 0;
end Buffer;

class Buffer {
private:
    PcoMutex mutex;
    PcoConditionVariable isFree, isFull;
    std::string buffer;
    bool bufferFull;

public:
    Buffer() : bufferFull(false) {}

    void put(std::string msg) {
        mutex.lock();
        while (bufferFull)
            isFree.wait(&mutex);
        buffer = msg;
        bufferFull = true;
        isFull.notifyOne();
        mutex.unlock();
    }

    std::string get() {
        std::string result;
        mutex.lock();
        while (!bufferFull)
            isFull.wait(&mutex);
        result = buffer;
        bufferFull = false;
        mutex.unlock();
        isFree.notifyOne();
        return result;
    }
};

class PcoHoareMonitor {
protected:
    class Condition {
        friend PcoHoareMonitor;
    public:
        Condition() : waitingSem(0), nbWaiting(0) {}
    private:
        PcoSemaphore waitingSem;
        int nbWaiting;
    };

    PcoHoareMonitor() : monitorMutex(1), monitorSignaled(0), monitorNbSignaled(0) {}
    void monitorIn()  { monitorMutex.acquire(); }
    void monitorOut() {
        if (monitorNbSignaled > 0) monitorSignaled.release();
        else monitorMutex.release();
    }
    void wait(Condition &cond) {
        cond.nbWaiting += 1;
        if (monitorNbSignaled > 0) monitorSignaled.release();
        else monitorMutex.release();
        cond.waitingSem.acquire();
        cond.nbWaiting -= 1;
    }
    void signal(Condition &cond) {
        if (cond.nbWaiting > 0) {
            monitorNbSignaled += 1;
            cond.waitingSem.release();
            monitorSignaled.acquire();
            monitorNbSignaled -= 1;
        }
    }
private:
    PcoSemaphore monitorMutex, monitorSignaled;
    int monitorNbSignaled;
};

// Usage (note: Hoare semantics allow `if`!):
class ProdConsoHoare : public PcoHoareMonitor {
    ITEM items[N];
    int head = 0, tail = 0, nbElements = 0;
    Condition notFull, notEmpty;
public:
    void put(ITEM item) {
        monitorIn();
        if (nbElements == N) wait(notFull);
        nbElements += 1;
        items[head] = item;
        head = (head + 1) % N;
        signal(notEmpty);
        monitorOut();
    }
    void get(ITEM *item) {
        monitorIn();
        if (nbElements == 0) wait(notEmpty);
        *item = items[tail];
        nbElements -= 1;
        tail = (tail + 1) % N;
        signal(notFull);
        monitorOut();
    }
};

// 1. Mutual exclusion with `synchronized` methods
class UniqueID {
    private int id;
    public synchronized int getNewID() { return id++; }
    public synchronized void decrID()  { id--; }
}

// 2. Weak Semaphore implemented with Java's Mesa monitor
public class Semaphore {
    private int value;
    public Semaphore(int initVal) { value = initVal; }

    public synchronized void semWait() throws InterruptedException {
        while (value <= 0) { // MUST be `while` (Mesa semantics!)
            wait();          // Suspends caller & releases object monitor lock
        }
        value--;
    }

    public synchronized void semPost() {
        value++;
        notify();            // Wakes one arbitrary thread (not FIFO!)
    }
}
